// MIT. K125 own native connected U tongue and side cap;immutable source arrays at rest.
import {Button} from '../../core/index.js';
import {THREE,FACE} from './geometry.js';
import {weightedInputHit} from '../../modeling/weighted-input.js';
import {spec} from './dimensions.js';
const smooth=x=>{x=THREE.MathUtils.clamp(x,0,1);return x*x*(3-2*x);};
class NativeInput extends Button{
 constructor(system,{id,label,position,face,travel,seed,eligible,weight,axis,scope}){super({id,label,position,quaternion:FACE[face],travel,longPressMs:0,meta:{role:'visual-control',actuation:'own-native-deformation',gpio:id==='button'?'G41':'RESET',surfaceCenter:position,surfaceFace:face,scope,travelSource:'own native/photo inferred visual travel;not rated mechanism'}});this.system=system;this.axis=axis;this.weightFunction=weight;this.weights=new Float32Array(system.rest.length/3);this.followers=[];this.lastDepth=0;const nodes=system.nodes,sf=system.shell.geometry.attributes.sourceFaceIndex,keys=system.keys;for(const n of nodes.values())n.near=new Set();for(let i=0;i<keys.length;i+=3)for(let j=0;j<3;j++)for(let k=0;k<3;k++){const a=nodes.get(keys[i+j]),b=nodes.get(keys[i+k]);if(eligible(a.p)&&eligible(b.p))a.near.add(keys[i+k]);}const start=Array.from(sf.array).map((f,i)=>({f,i,n:nodes.get(keys[i])})).filter(q=>q.f===seed&&eligible(q.n.p)).sort((a,b)=>weight(b.n.p)-weight(a.n.p))[0];if(!start)throw new Error('K125 own input seed absent '+id);const seen=new Set(),queue=[keys[start.i]];for(let j=0;j<queue.length;j++){const key=queue[j];if(seen.has(key))continue;seen.add(key);const n=nodes.get(key);for(const i of n.indices)this.weights[i]=weight(n.p);queue.push(...n.near);}this.meta.connectedNativeVertices=seen.size;this.meta.movingNativeVertices=this.weights.filter(w=>w>0).length;system.inputs.push(this);}
 follow(o,w=1){this.followers.push({o,w,rest:o.position.clone()});}
 update(dt){const changed=super.update(dt),d=this.getActuationState().depthMm;if(d!==this.lastDepth){this.lastDepth=d;this.system.apply();return true;}return changed;}
 dispose(){this.lastDepth=0;this.system.apply();super.dispose();this.system.inputs=this.system.inputs.filter(x=>x!==this);this.system=null;this.weights=null;this.followers=[];}
}
export function nativeInputs(host,shell,assembly){shell.updateWorldMatrix(true,false);const rest=shell.geometry.attributes.position.array.slice(),restNormal=shell.geometry.attributes.normal.array.slice(),matrix=shell.matrix.clone(),inverse=matrix.clone().invert(),rotation=new THREE.Matrix3().setFromMatrix4(matrix),inverseRotation=rotation.clone().invert(),nodes=new Map(),keys=[],world=[];for(let i=0;i<rest.length/3;i++){const k=i*3,p=new THREE.Vector3(rest[k],rest[k+1],rest[k+2]).applyMatrix4(matrix),key=[rest[k],rest[k+1],rest[k+2]].map(x=>Math.round(x*1e5)).join(',');keys.push(key);world.push(p);let n=nodes.get(key);if(!n)nodes.set(key,n={p,indices:[],near:new Set()});n.indices.push(i);}const system={shell,rest,restNormal,matrix,inverse,rotation,inverseRotation,nodes,keys,world,inputs:[],apply(){const p=shell.geometry.attributes.position,n=shell.geometry.attributes.normal;if(this.inputs.every(b=>b.lastDepth===0)){p.array.set(rest);n.array.set(restNormal);}else for(let i=0;i<world.length;i++){const v=world[i].clone(),normal=new THREE.Vector3(restNormal[i*3],restNormal[i*3+1],restNormal[i*3+2]).applyMatrix3(rotation);for(const b of this.inputs){const d=b.lastDepth,w=b.weights[i];if(!d||!w)continue;v.addScaledVector(b.axis,d*w);const eps=1e-3,gradient=new THREE.Vector3();for(let k=0;k<3;k++){const a=world[i].clone(),c=world[i].clone();a.setComponent(k,a.getComponent(k)+eps);c.setComponent(k,c.getComponent(k)-eps);gradient.setComponent(k,(b.weightFunction(a)-b.weightFunction(c))/(2*eps));}normal.addScaledVector(gradient,-d*b.axis.dot(normal)/(1+d*gradient.dot(b.axis)));}v.applyMatrix4(inverse);normal.applyMatrix3(inverseRotation).normalize();p.setXYZ(i,...v.toArray());n.setXYZ(i,...normal.toArray());}p.needsUpdate=true;n.needsUpdate=true;shell.geometry.computeBoundingBox();shell.geometry.computeBoundingSphere();for(const b of this.inputs)for(const f of b.followers)f.o.position.copy(f.rest).addScaledVector(b.axis,b.lastDepth*f.w);}};
 const button=host.add(new NativeInput(system,{id:'button',label:'K125 actual native U tongue · G41',position:[0,-1.5,5.15],face:'front',travel:spec.travelMm.button,seed:3717,eligible:p=>p.y> -5.75&&p.y<4.8&&p.z>2.4&&Math.abs(p.x)<5.31,weight:p=>THREE.MathUtils.clamp((p.y+5.75)/10.3,0,1),axis:new THREE.Vector3(0,0,-1),scope:'Input intent only;no microphone/RGB or firmware action'}));
 const resetWeight=p=>smooth((p.y-8.85)/.4)*smooth((13.75-p.y)/.4)*smooth((p.z+2.15)/.32)*smooth((1.2-p.z)/.32);
 const reset=host.add(new NativeInput(system,{id:'reset',label:'K125 actual native side Reset cap',position:[-10.5,11.3,-.5],face:'left',travel:spec.travelMm.reset,seed:6013,eligible:p=>p.x< -8.4&&p.y>8.85&&p.y<13.75&&p.z> -2.15&&p.z<1.2,weight:resetWeight,axis:new THREE.Vector3(1,0,0),scope:'Input intent only;no reboot/download/automatic status effects'}));
 const frame=new THREE.Group();frame.name='K125 shared native input routing frame';shell.parent.add(frame);frame.add(shell);button.hit(shell,h=>weightedInputHit(button,shell,h));reset.hit(frame,h=>weightedInputHit(reset,shell,h));reset.follow(assembly.resetPlunger);assembly.inputs=system;assembly.button=button;assembly.reset=reset;return system;
}
